arguments.command:
cat /app/resources/treasury_bulletin_1977_03.json | python3 -c "
import json, sys
data = json.load(sys.stdin)
elements = data['document']['elements']
for i, el in enumerate(elements):
    if 'table' in el and el.get('table', {}).get('title'):
        print(f'Element {i} title:', el['table'].get('title'))
    if 'text' in el:
        text = el.get('text', '')[:100]
        if 'ownership' in text.lower() or 'survey' in text.lower():
            print(f'Element {i} text:', text)
" 2>/dev/null | head -50
